<?php
require_once dirname(__DIR__) . '/includes/functions.php';
osis_require_role('anggota');
$pageTitle = 'Dashboard anggota';
$stmt = $pdo->prepare('SELECT * FROM anggota WHERE user_id=? LIMIT 1'); $stmt->execute([osis_current_user()['id']]); $member = $stmt->fetch();
$reportCount = 0; $taskCount = 0; $attendance = ['hadir'=>0,'izin'=>0,'sakit'=>0,'alpa'=>0]; $recentReports = [];
if ($member) {
    $stmt = $pdo->prepare('SELECT COUNT(*) FROM laporan WHERE anggota_id=?'); $stmt->execute([$member['id']]); $reportCount = (int)$stmt->fetchColumn();
    $stmt = $pdo->prepare("SELECT COUNT(*) FROM tugas_penerima p JOIN tugas t ON t.id=p.tugas_id WHERE p.anggota_id=? AND t.status='aktif'"); $stmt->execute([$member['id']]); $taskCount = (int)$stmt->fetchColumn();
    $stmt = $pdo->prepare('SELECT status, COUNT(*) AS total FROM absensi WHERE anggota_id=? GROUP BY status'); $stmt->execute([$member['id']]); foreach ($stmt->fetchAll() as $row) { $attendance[$row['status']] = (int)$row['total']; }
    $stmt = $pdo->prepare('SELECT l.*, k.nama AS kategori FROM laporan l LEFT JOIN kategori_laporan k ON k.id=l.kategori_id WHERE l.anggota_id=? ORDER BY l.created_at DESC LIMIT 4'); $stmt->execute([$member['id']]); $recentReports = $stmt->fetchAll();
}
require dirname(__DIR__) . '/includes/header.php';
?>
<section class="member-dashboard section section-paper"><div class="container"><div class="member-welcome"><div><span class="eyebrow">DASHBOARD ANGGOTA</span><h1>Hai, <?= osis_e(osis_current_user()['nama']) ?><span class="text-accent">.</span></h1><p>Ruang pribadi untuk melihat perkembangan laporan dan kehadiranmu.</p></div><div class="member-welcome-actions"><a class="button button-outline" href="<?= osis_e(osis_url('anggota/tugas.php')) ?>">Tugas saya <span>↗</span></a><a class="button button-primary" href="<?= osis_e(osis_url('anggota/laporan-kirim.php')) ?>">Kirim aspirasi <span>↗</span></a></div></div>
<?php if (!$member): ?><div class="alert alert-warning">Akunmu belum terhubung dengan data anggota. Silakan hubungi admin OSIS.</div><?php else: ?><div class="dashboard-stat-grid"><div class="dashboard-stat"><span class="stat-symbol">▱</span><span class="eyebrow">LAPORAN DIKIRIM</span><strong><?= $reportCount ?></strong><span class="stat-detail">Semua aspirasi yang kamu kirim</span></div><div class="dashboard-stat"><span class="stat-symbol stat-green">✓</span><span class="eyebrow">HADIR</span><strong><?= $attendance['hadir'] ?></strong><span class="stat-detail">Dari seluruh sesi yang tercatat</span></div><div class="dashboard-stat"><span class="stat-symbol stat-coral">◷</span><span class="eyebrow">IZIN / SAKIT</span><strong><?= $attendance['izin'] + $attendance['sakit'] ?></strong><span class="stat-detail">Tetap cek rekap kehadiranmu</span></div><div class="dashboard-stat dashboard-stat-task"><span class="stat-symbol">☷</span><span class="eyebrow">TUGAS AKTIF</span><strong><?= $taskCount ?></strong><span class="stat-detail"><a href="<?= osis_e(osis_url('anggota/tugas.php')) ?>">Buka daftar tugas ↗</a></span></div></div><div class="member-dashboard-grid"><section class="panel-card"><div class="panel-heading"><div><span class="eyebrow">PEMBARUAN TERAKHIR</span><h2>Laporan saya</h2></div><a class="text-link" href="<?= osis_e(osis_url('anggota/laporan-saya.php')) ?>">Semua laporan ↗</a></div><?php if ($recentReports): ?><div class="compact-list"><?php foreach ($recentReports as $report): ?><a class="compact-row" href="<?= osis_e(osis_url('anggota/laporan-saya.php')) ?>"><span class="compact-icon">▱</span><span class="compact-copy"><strong><?= osis_e($report['judul']) ?></strong><small><?= osis_e($report['kategori'] ?: 'Aspirasi') ?> · <?= osis_e(osis_format_date($report['created_at'])) ?></small></span><span class="badge badge-status badge-<?= osis_e($report['status']) ?>"><?= osis_e(ucfirst($report['status'])) ?></span></a><?php endforeach; ?></div><?php else: ?><p class="muted-copy">Kamu belum mengirim laporan atau aspirasi.</p><a class="text-link" href="<?= osis_e(osis_url('anggota/laporan-kirim.php')) ?>">Kirim laporan pertama ↗</a><?php endif; ?></section><section class="member-quick-links"><span class="eyebrow">AKSES CEPAT</span><h2>Kelola akunmu</h2><a href="<?= osis_e(osis_url('anggota/absensi-saya.php')) ?>"><span>✓</span><span><strong>Rekap absensi</strong><small>Lihat kehadiran setiap sesi</small></span><b>↗</b></a><a href="<?= osis_e(osis_url('anggota/profil.php')) ?>"><span>♙</span><span><strong>Profil saya</strong><small>Perbarui data anggota</small></span><b>↗</b></a><a href="<?= osis_e(osis_url('anggota/laporan-kirim.php')) ?>"><span>＋</span><span><strong>Kirim laporan</strong><small>Sampaikan masukan ke OSIS</small></span><b>↗</b></a><a href="<?= osis_e(osis_url('anggota/tugas.php')) ?>"><span>☷</span><span><strong>Tugas saya</strong><small>Kirim laporan dan dokumentasi tugas</small></span><b>↗</b></a></section></div><?php endif; ?></div></section>
